sql.where:
r.ELIMINADA = FALSE
AND r.PUBLICADA = TRUE AND r.OCULTA = FALSE
AND r.OCULTA = TRUE
AND r.USUARIO = #{filtro.autor}

    AND EXISTS (SELECT 1 FROM like_receta lm WHERE lm.RECETA = r.ID AND lm.USUARIO = #{filtro.meGustaDe})

AND r.TITULO LIKE #{filtro.titulo} ESCAPE '\\'
AND r.TIPO = #{filtro.tipo}
AND r.USUARIO LIKE #{filtro.usuario} ESCAPE '\\'
AND r.DIFICULTAD = #{filtro.dificultad}
AND r.COMENSALES >= #{filtro.comensales}
AND r.TIEMPO <= #{filtro.tiempoMax}


    AND (SELECT COUNT(DISTINCT ir.INGREDIENTE)
         FROM ingrediente_receta ir
         WHERE ir.RECETA = r.ID
           AND ir.INGREDIENTE IN

               #{ingrediente}

        ) = #{numeroIngredientes}


    AND NOT EXISTS (
        SELECT 1
        FROM ingrediente_receta ire
        JOIN ingredientes ie ON ie.ID = ire.INGREDIENTE
        WHERE ire.RECETA = r.ID
          AND ie.GRUPO IN

              #{grupo}

    )

mapper.update:
UPDATE recetas
SET TITULO = #{titulo}, INSTRUCCIONES = #{instrucciones}, TIPO = #{tipo}, IMAGEN = #{imagen},
    TIEMPO = #{tiempo}, COMENSALES = #{comensales}, DIFICULTAD = #{dificultad}
WHERE ID = #{id}
